function Get-AdcsSchannelInfo {
        $ = [ordered]@{
MappingValue = $NUll
 UpnMapping   = $fALSE
        ServiceState = $NUll
      }
         try {
   $ = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\SCHANNEL' -Name 'CertificateMappingMethods' -ErrorAction Stop
       $.MappingValue = $.CertificateMappingMethods
       if (($.CertificateMappingMethods -band 0x4) -eq 0x4) { $.UpnMapping = $TruE }
   }
       catch { }
       $ = Get-Service -Name certsrv -ErrorAction SilentlyContinue
   if ($) { $.ServiceState = $.Status }
     return [pscustomobject]$
}


