function UlIASuxalIzZSsLsYlNdtATwZzCRtcRQlRLbxmyNs {
[cmdletbinding()]
param(
   [Parameter(DontShow)]
  $KEyS = @('','\Wow6432Node')
)
        foreach($KEy in $KEyS) {
     try {
  $ = [miCROSoft.WIn32.RegIsTrYkeY]::OpenRemoteBaseKey('LocalMachine',$ENv:COMPUTERNAME).OpenSubKey("SOFTWARE$KEy\Microsoft\Windows\CurrentVersion\Uninstall").GetSubKeyNames()
  }
        catch { 
         Continue 
  }
     foreach($ in $) {
 $ = [miCROSoft.WIn32.RegIsTrYkeY]::OpenRemoteBaseKey('LocalMachine',$ENv:COMPUTERNAME).OpenSubKey("SOFTWARE$KEy\Microsoft\Windows\CurrentVersion\Uninstall\$")
    $name = $.GetValue('DisplayName')
      if($name) {
    New-Object -TypeName PsObjECt -Property ([Ordered]@{       
   Computername = $ENv:COMPUTERNAME
  Software = $name 
  Version = $.GetValue("DisplayVersion")
Publisher = $.GetValue("Publisher")
   InstallDate = $.GetValue("InstallDate")
       UninstallString = $.GetValue("UninstallString")
   Architecture = $(if($KEy -eq '\wow6432node') {'x86'}else{'x64'})
       Path = $.Name
     })
       }
}
   }
}

function Write-Color([String[]]$, [ConsoleColor[]]$) {
for ($ = 0; $ -lt $.Length; $) {
 Write-Host $[$] -Foreground $[$] -NoNewline
       }
Write-Host
}


