Write-Host ""
if ($TimEstAmP) { TimeElapsed }
Write-Host -ForegroundColor Blue "=========|| Testing access to c:\windows\system32\tasks"
if (Get-ChildItem "c:\windows\system32\tasks" -ErrorAction SilentlyContinue) {
Write-Host "Access confirmed, may need futher investigation"
    Get-ChildItem "c:\windows\system32\tasks"
}
else {
      Write-Host "No admin access to scheduled tasks folder."
       Get-ScheduledTask | Where-Object { $_.TaskPath -notlike "\Microsoft*" } | ForEach-Object {
     $ = $_.Actions.Execute
    if ($ -ne $NUll) {
     foreach ($ in $) {
if ($ -like "%windir%*") { $ = $.replace("%windir%", $EnV:windir) }
     elseif ($ -like "%SystemRoot%*") { $ = $.replace("%SystemRoot%", $EnV:windir) }
  elseif ($ -like "%localappdata%*") { $ = $.replace("%localappdata%", "$ENv:UserProfile\appdata\local") }
   elseif ($ -like "%appdata%*") { $ = $.replace("%localappdata%", $ENv:Appdata) }
  $ = $.Replace('"', '')
  YfLEUjTsoHwqoVtEkUbNFLZPpktmRuviHmMIjJeG -Target $
   Write-Host "`n"
   Write-Host "TaskName: $($_.TaskName)"
 Write-Host "-------------"
   New-Object -TypeName PsObjECt -Property ([Ordered]@{
        LastResult = $(($_ | Get-ScheduledTaskInfo).LastTaskResult)
NextRun    = $(($_ | Get-ScheduledTaskInfo).NextRunTime)
   Status     = $_.State
       Command    = $_.Actions.execute
       Arguments  = $_.Actions.Arguments 
}) | Write-Host
 } 
}
     }
}


